tings":{"title":"How Much Will Your Hyperlocal Marketing SaaS Dream Really Cost? A No-Nonsense Guide","title_color":"#FFFFFF","typography_typography":"custom","typography_font_size_mobile":{"unit":"px","size":24,"sizes":[]},"typography_font_weight":"700","typography_line_height_mobile":{"unit":"em","size":1.5,"sizes":[]},"typography_letter_spacing_mobile":{"unit":"px","size":0.3,"sizes":[]},"header_size":"p"},"elements":[],"widgetType":"heading"},{"id":"077408c","elType":"widget","settings":{"space_mobile":{"unit":"px","size":20,"sizes":[]}},"elements":[],"widgetType":"spacer"},{"id":"ab10347","elType":"widget","settings":{"editor":"<a style="color: white; text-decoration: none;" href="https://reapmind.com">
